let data = msg.payload;
if (typeof data === 'string') {
  try { data = JSON.parse(data); } catch(e) { return [null, { payload: { error: 'invalid_json', raw: data } }]; }
}

// Mandatory field checks
if (!data || !data.store_id || !data.product_id || typeof data.quantity !== 'number') {
  return [null, { payload: { reason: 'missing_fields', data: data } }];
}

// Out-of-range / noise filtering rule
if (data.quantity < 0) {
  return [null, { payload: { reason: 'out_of_range_noise', quantity: data.quantity, product_id: data.product_id, store_id: data.store_id, timestamp: new Date().toISOString() } }];
}

// Enrich telemetry with edge metadata
data.gateway_id = 'NODE-RED-EDGE-01';
data.edge_processed_at = new Date().toISOString();

// Low stock threshold checking
const thresholds = { 'SKU-1001': 15, 'SKU-1002': 10, 'SKU-1003': 20 };
const threshold = thresholds[data.product_id] || 10;

data.low_stock_warning = data.quantity <= threshold;
data.threshold = threshold;

msg.payload = data;
// Output 1: Valid Telemetry, Output 2: Dropped Noise
return [msg, null];

const p = msg.payload;
msg.url = 'http://localhost:3001/inventory/' + p.store_id + '/' + p.product_id;
msg.method = 'PUT';
msg.headers = { 'content-type': 'application/json' };
msg.payload = {
  on_hand_qty: p.quantity,
  last_sensor: p.sensor_type,
  source: 'node-red-gateway'
};
return msg;

const p = msg.payload;
msg.payload = {
  event_type: 'LOW_STOCK_ALERT',
  store_id: p.store_id,
  shelf_id: p.shelf_id,
  product_id: p.product_id,
  current_quantity: p.quantity,
  threshold: p.threshold,
  timestamp: new Date().toISOString(),
  action: 'TRIGGER_EOQ_REORDER'
};
return msg;
